async function signIn(event){event.preventDefault();const button=event.target.querySelector('button');button.disabled=true;button.textContent='Signing in…';try{state.user=(await api('/api/auth/login',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(event.target)))})).user;await dashboard()}catch(error){button.disabled=false;button.innerHTML='Sign in <span>→</span>';toast(error.message)}}
function transaction(t){return `<div class="txn-v2"><div class="txn-title"><span class="txn-icon">↗</span><div><b>${escapeText(t.recipient_name)}</b><small>${escapeText(t.description||'Transfer')} · ${escapeText(t.reference)}</small></div></div><div style="text-align:right"><b>${money(t.amount)}</b><small><span class="status-dot"></span>${escapeText(t.status)}</small></div></div>`}function switchAccount(id){state.account=state.data.accounts.find(a=>a.id===id);dashboard()}
function openTransfer(){app.insertAdjacentHTML('beforeend',`<div class="modal-v2"><div><div class="topline"><h2>New transfer</h2><button class="close" onclick="this.closest('.modal-v2').remove()">Close</button></div><form id="transfer-form"><div class="form-field"><label>Recipient name</label><input name="recipientName" required></div><div class="form-field"><label>Account number</label><input name="recipientAccount" required></div><div class="form-field"><label>Recipient bank</label><input name="recipientBank" required></div><div class="form-field"><label>Amount in USD</label><input name="amount" type="number" min="1" required></div><div class="form-field"><label>Description</label><input name="description"></div><button class="cta" style="margin-top:24px">Review transfer →</button></form></div></div>`);document.querySelector('#transfer-form').onsubmit=sendTransfer}
async function sendTransfer(event){event.preventDefault();try{const result=await api('/api/customer/transfers',{method:'POST',body:JSON.stringify({...Object.fromEntries(new FormData(event.target)),accountId:state.account.id})});document.querySelector('.modal-v2').remove();toast(`${result.message} Reference: ${result.reference}`);await dashboard()}catch(error){toast(error.message)}}
async function receipt(id){const data=await api(`/api/customer/transactions/${id}/receipt`);const t=data.transaction;app.innerHTML=`<main class="site"><section class="login-card" style="max-width:680px;margin:40px auto"><div class="wordmark">Aurum</div><span class="kicker" style="color:#55737b">Transfer receipt</span><h1 style="font-size:48px">${escapeText(t.status)}</h1><div class="txn-v2"><span>Amount</span><b>${money(t.amount)}</b></div><div class="txn-v2"><span>Recipient</span><b>${escapeText(t.recipient_name)}</b></div><div class="txn-v2"><span>Reference</span><b>${escapeText(t.reference)}</b></div><div class="actions"><button class="cta" onclick="window.print()">Print receipt</button><button class="ghost" onclick="dashboard()">Back to overview</button></div></section></main>`}
async function adminSignIn(event){event.preventDefault();const button=event.target.querySelector('button');button.disabled=true;button.textContent='Signing in…';try{state.user=(await api('/api/auth/login',{method:'POST',body:JSON.stringify({...Object.fromEntries(new FormData(event.target)),role:'admin'})})).user;await adminDashboard()}catch(error){button.disabled=false;button.innerHTML='Enter operations <span>→</span>';toast(error.message)}}
async function adminSetting(key,value){try{await api('/api/admin/settings',{method:'PATCH',body:JSON.stringify({key,value})});toast('System setting saved.');adminDashboard()}catch(error){toast(error.message)}}async function adminSignOut(){await api('/api/auth/logout',{method:'POST'});location.assign('/admin')}async function signOut(){await api('/api/auth/logout',{method:'POST'});state={user:null,data:null,account:null};home()}function toast(message){const e=document.createElement('div');e.className='toast';e.textContent=message;document.body.append(e);setTimeout(()=>e.remove(),4000)}
